// Prepara la petición de refresco de token.
// Requiere las variables de entorno HC_CLIENT_ID (y HC_CLIENT_SECRET si tu app la tiene).
const t = global.get("hc_tokens", "file") || {};
if (!t.refresh_token) {
    node.status({fill: "red", shape: "ring", text: "sin refresh_token"});
    node.warn("No hay refresh_token guardado. Ejecuta una vez el Device Flow a mano " +
              "y guarda el resultado con: global.set('hc_tokens', {...}, 'file')");
    return null;
}
const body = {
    grant_type: "refresh_token",
    refresh_token: t.refresh_token,
    client_id: env.get("HC_CLIENT_ID")
};
const secret = env.get("HC_CLIENT_SECRET");
if (secret) { body.client_secret = secret; }

msg.method = "POST";
msg.url = "https://api.home-connect.com/security/oauth/token";
msg.headers = {"Content-Type": "application/x-www-form-urlencoded"};
msg.payload = new URLSearchParams(body).toString();
return msg;

// Guarda los tokens en el context store de fichero (sobreviven a reinicios).
// OJO: el refresh_token rota en cada refresco; hay que guardar siempre el ultimo.
const r = msg.payload;
if (!r || !r.access_token) {
    node.status({fill: "red", shape: "dot", text: "refresco fallido"});
    node.error("Refresco de token fallido: " + JSON.stringify(r), msg);
    return [null, msg];
}
const previo = global.get("hc_tokens", "file") || {};
const t = {
    access_token: r.access_token,
    refresh_token: r.refresh_token || previo.refresh_token,
    expires_at: Date.now() + ((r.expires_in || 86400) * 1000)
};
global.set("hc_tokens", t, "file");
node.status({fill: "green", shape: "dot", text: "token ok hasta " + new Date(t.expires_at).toLocaleString()});
return [{topic: "sse/control", payload: "start"}, null];

// Cliente SSE de Home Connect con reconexion, backoff y reciclado periodico.
// Entrada: msg.payload = "start" | "stop"
// Salida 1: eventos del horno   Salida 2: mensajes de control (refresco / resync)
// Requiere: pestaña "Setup" -> Modules -> https  (variable: https)

const MAX_BACKOFF = 60000;      // tope de reintento
const RECYCLE_MS  = 15 * 60000; // reciclar el stream cada 15 min
const KA_TIMEOUT  = 150000;     // sin keep-alive 2.5 min -> reconectar

function bump() {
    const g = (context.get("gen") || 0) + 1;
    context.set("gen", g);
    return g;
}
function clearTimers() {
    ["retryTimer", "kaTimer", "recycleTimer"].forEach(function (k) {
        const t = context.get(k);
        if (t) { clearTimeout(t); }
        context.set(k, null);
    });
}
function destroyReq() {
    const req = context.get("req");
    if (req) { try { req.destroy(); } catch (e) { /* ignorar */ } }
    context.set("req", null);
}
function stop() {
    bump();
    clearTimers();
    destroyReq();
    node.status({fill: "grey", shape: "ring", text: "parado"});
}
function reconnect(motivo) {
    bump();
    clearTimers();
    destroyReq();
    const b = context.get("backoff") || 1000;
    node.status({fill: "yellow", shape: "ring", text: "reintento en " + Math.round(b / 1000) + "s (" + motivo + ")"});
    context.set("backoff", Math.min(b * 2, MAX_BACKOFF));
    context.set("retryTimer", setTimeout(connect, b));
}

function connect() {
    bump();
    clearTimers();
    destroyReq();
    const g = context.get("gen");
    const vivo = function () { return g === context.get("gen"); };

    const tokens = global.get("hc_tokens", "file") || {};
    const haId = env.get("HC_HAID");
    if (!tokens.access_token || !haId) {
        node.status({fill: "red", shape: "ring", text: "falta token o HC_HAID"});
        return reconnect("sin credenciales");
    }

    const req = https.request({
        hostname: "api.home-connect.com",
        path: "/api/homeappliances/" + haId + "/events",
        method: "GET",
        headers: {
            "Authorization": "Bearer " + tokens.access_token,
            "Accept": "text/event-stream"
        }
    }, function (res) {
        if (!vivo()) { res.resume(); return; }
        if (res.statusCode === 401) {
            res.resume();
            node.send([null, {topic: "hc/auth", payload: "refresh"}]);
            return reconnect("401 token caducado");
        }
        if (res.statusCode !== 200) {
            res.resume();
            return reconnect("HTTP " + res.statusCode);
        }

        context.set("backoff", 1000);
        node.status({fill: "green", shape: "dot", text: "conectado"});
        // Resincronizar: los cambios ocurridos mientras estabamos caidos no se reenvian.
        node.send([null, {topic: "hc/resync", payload: true}]);

        const armKA = function () {
            const t = context.get("kaTimer");
            if (t) { clearTimeout(t); }
            context.set("kaTimer", setTimeout(function () {
                if (vivo()) { reconnect("sin keep-alive"); }
            }, KA_TIMEOUT));
        };
        armKA();
        context.set("recycleTimer", setTimeout(function () {
            if (vivo()) { reconnect("reciclado periodico"); }
        }, RECYCLE_MS));

        let buf = "";
        res.setEncoding("utf8");
        res.on("data", function (chunk) {
            if (!vivo()) { return; }
            armKA();
            buf += chunk;
            let idx;
            while ((idx = buf.indexOf("\n\n")) >= 0) {
                const bloque = buf.slice(0, idx);
                buf = buf.slice(idx + 2);
                const ev = {event: "", data: "", id: ""};
                bloque.split("\n").forEach(function (linea) {
                    if (linea.indexOf("event:") === 0) { ev.event = linea.slice(6).trim(); }
                    else if (linea.indexOf("data:") === 0) { ev.data += linea.slice(5).trim(); }
                    else if (linea.indexOf("id:") === 0) { ev.id = linea.slice(3).trim(); }
                });
                if (!ev.event || ev.event === "KEEP-ALIVE") { continue; }
                let payload = null;
                if (ev.data) {
                    try { payload = JSON.parse(ev.data); } catch (e) { payload = ev.data; }
                }
                node.send([{topic: "homeconnect/" + ev.event, event: ev.event, payload: payload}, null]);
            }
        });
        res.on("end", function () { if (vivo()) { reconnect("stream cerrado"); } });
        res.on("error", function (e) { if (vivo()) { reconnect("error stream: " + e.message); } });
    });

    req.on("error", function (e) { if (vivo()) { reconnect("error peticion: " + e.message); } });
    req.end();
    context.set("req", req);
}

const cmd = (msg && msg.payload) || "start";
if (cmd === "stop") { stop(); }
else { context.set("backoff", 1000); connect(); }
return null;

