// Tras cada (re)conexion: leer estado y settings actuales, porque los cambios
// ocurridos mientras el stream estaba caido no se reenvian.
const token = (global.get("hc_tokens", "file") || {}).access_token;
const haId = env.get("HC_HAID");
if (!token || !haId) { return null; }
const base = "https://api.home-connect.com/api/homeappliances/" + haId;
const cab = {"Authorization": "Bearer " + token, "Accept": "application/vnd.bsh.sdk.v1+json"};
return [
    {method: "GET", url: base + "/status",   headers: cab, payload: null},
    {method: "GET", url: base + "/settings", headers: cab, payload: null}
];

// Convierte la respuesta de /status o /settings al mismo formato que los eventos SSE.
const d = (msg.payload && msg.payload.data) || {};
const items = d.status || d.settings || [];
if (!items.length) { return null; }
return {event: "RESYNC", payload: {items: items}};

// Maquina de estados del horno -> global.horno
// Entrada: eventos SSE (msg.event + msg.payload.items) o resync (/status, /settings)
// Salida 1: estado completo   Salida 2: solo transiciones (para la logica de cargas)

// Potencias ESTIMADAS en W. Calibrar con un medidor real la primera semana.
const P = {
    STANDBY:     3,
    CALENTANDO:  3000,
    MANTENIENDO: 1400,
    PIROLISIS:   3000
};

const st = global.get("horno") || {
    conectado: false, encendido: false, estado: "APAGADO",
    potenciaEstimadaW: 0, fuente: "estimado"
};
const anterior = st.estado;

if (msg.event === "CONNECTED")    { st.conectado = true; }
if (msg.event === "DISCONNECTED") { st.conectado = false; }

const items = (msg.payload && msg.payload.items) || [];
items.forEach(function (it) {
    const v = it.value;
    switch (it.key) {
        case "BSH.Common.Setting.PowerState":
            st.encendido = /\.On$/.test(String(v));
            if (!st.encendido) { st.preheatHecho = false; st.programa = null; }
            break;
        case "BSH.Common.Status.OperationState":
            st.operationState = String(v).split(".").pop();
            break;
        case "BSH.Common.Status.DoorState":
            st.puerta = String(v).split(".").pop();
            break;
        case "BSH.Common.Root.ActiveProgram":
        case "BSH.Common.Root.SelectedProgram":
            st.programa = v;
            st.preheatHecho = false;
            break;
        case "BSH.Common.Option.RemainingProgramTime":
            st.restanteS = v;
            st.finEstimado = new Date(Date.now() + (v * 1000)).toISOString();
            break;
        case "BSH.Common.Option.ProgramProgress":
            st.progreso = v;
            break;
        case "Cooking.Oven.Status.CurrentCavityTemperature":
            st.temperaturaCavidad = v;
            break;
        case "Cooking.Oven.Option.SetpointTemperature":
            st.temperaturaObjetivo = v;
            break;
        case "Cooking.Oven.Event.PreheatFinished":
        case "Cooking.Oven.Event.RegularPreheatFinished":
            if (/Present$/.test(String(v))) { st.preheatHecho = true; }
            break;
        case "BSH.Common.Event.ProgramFinished":
            if (/Present$/.test(String(v))) { st.preheatHecho = false; }
            break;
    }
});

// --- Derivar estado ---
const op = st.operationState || "Inactive";
const pirolisis = /Pyrolysis|Cleaning/i.test(String(st.programa || ""));

if (!st.encendido)                 { st.estado = "APAGADO"; }
else if (op === "DelayedStart")    { st.estado = "DIFERIDO"; }
else if (op === "Run")             { st.estado = st.preheatHecho ? "MANTENIENDO" : "CALENTANDO"; }
else if (op === "Pause")           { st.estado = "PAUSA"; }
else if (op === "Finished")        { st.estado = "FIN"; }
else                               { st.estado = "EN_ESPERA"; }

// --- Derivar potencia estimada ---
if (st.estado === "CALENTANDO")       { st.potenciaEstimadaW = pirolisis ? P.PIROLISIS : P.CALENTANDO; }
else if (st.estado === "MANTENIENDO") { st.potenciaEstimadaW = pirolisis ? P.PIROLISIS : P.MANTENIENDO; }
else                                  { st.potenciaEstimadaW = P.STANDBY; }

// Fallback de seguridad: si la nube se cae con el horno encendido, asumir el peor
// caso en vez de dar por hecho que no consume.
if (!st.conectado && st.encendido) {
    st.potenciaEstimadaW = P.CALENTANDO;
    st.fuente = "estimado-degradado";
} else {
    st.fuente = "estimado";
}

st.ts = Date.now();
global.set("horno", st);

const salidaEstado = {topic: "horno/estado", payload: st};
const transicion = (anterior !== st.estado)
    ? {topic: "horno/transicion", payload: {de: anterior, a: st.estado, estado: st}}
    : null;

node.status({fill: st.estado === "APAGADO" ? "grey" : "green", shape: "dot",
             text: st.estado + " ~" + st.potenciaEstimadaW + "W"});
return [salidaEstado, transicion];
